package com.wildcreatures.client;

import com.wildcreatures.entity.AbstractDragon;
import net.minecraft.client.model.HierarchicalModel;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.util.Mth;

/**
 * Pose and animation for the dragons. Every kind of dragon uses this skeleton; they differ in texture, and the
 * Sea Dragon has fins instead of spikes. The boxes themselves come from DragonLayer (generated by tools/make_dragon.py).
 */
public class DragonModel<T extends AbstractDragon> extends HierarchicalModel<T> {
    private final ModelPart root, body, neck1, neck2, head, jaw;
    private final ModelPart tail1, tail2, tail3, tail4;
    private final ModelPart[] legs = new ModelPart[4], shins = new ModelPart[4];
    private final ModelPart wingR, wingL, wingTipR, wingTipL;
    /** The back spikes where a saddle goes (hidden while it wears one). The Sea Dragon's body has none. */
    private final ModelPart saddleSpikes;

    public DragonModel(ModelPart root) {
        this.root = root;
        body = root.getChild("body");
        neck1 = body.getChild("neck1");
        neck2 = neck1.getChild("neck2");
        head = neck2.getChild("head");
        jaw = head.getChild("jaw");
        tail1 = body.getChild("tail1");
        tail2 = tail1.getChild("tail2");
        tail3 = tail2.getChild("tail3");
        tail4 = tail3.getChild("tail4");
        String[] names = {"front_leg_r", "front_leg_l", "hind_leg_r", "hind_leg_l"};
        String[] shinNames = {"front_shin_r", "front_shin_l", "hind_shin_r", "hind_shin_l"};
        for (int i = 0; i < 4; i++) {
            legs[i] = body.getChild(names[i]);
            shins[i] = legs[i].getChild(shinNames[i]);
        }
        wingR = body.getChild("wing_r");
        wingL = body.getChild("wing_l");
        wingTipR = wingR.getChild("wing_tip_r");
        wingTipL = wingL.getChild("wing_tip_l");
        saddleSpikes = body.hasChild("saddle_spikes") ? body.getChild("saddle_spikes") : null;
    }

    @Override
    public ModelPart root() { return root; }

    /** The body part, which everything else hangs off (the saddle is drawn on it). */
    public ModelPart body() { return body; }

    @Override
    public void setupAnim(T dragon, float limbSwing, float limbSwingAmount, float age, float netHeadYaw, float headPitch) {
        root.getAllParts().forEach(ModelPart::resetPose);
        if (saddleSpikes != null) saddleSpikes.visible = !dragon.isSaddled();
        float pt = age - dragon.tickCount;
        float fly = dragon.getFlyAnim(pt);
        float breath = dragon.getBreathAnim(pt);
        float bite = dragon.getBiteAnim(pt);
        float swim = dragon.getSwimAnim(pt);
        float ground = 1.0F - fly;
        // swimming: how hard it's stroking (0 drifting, 1 full speed) and where it is in the stroke
        float pace = Math.min(limbSwingAmount, 1.0F) * swim;
        float stroke = age * 0.1F + limbSwing * 0.25F;

        // ---- head and neck: looking around, spread over the neck so it bends smoothly
        float yaw = netHeadYaw * Mth.DEG_TO_RAD;
        float pitch = headPitch * Mth.DEG_TO_RAD;
        neck1.yRot += yaw * 0.3F;
        neck2.yRot += yaw * 0.3F;
        head.yRot += yaw * 0.4F;
        head.xRot += pitch;

        // ---- idle breathing
        float idle = Mth.sin(age * 0.08F);
        body.y += idle * 0.25F * ground;
        neck1.xRot += idle * 0.03F;
        jaw.xRot += (idle * 0.5F + 0.5F) * 0.05F;

        // ---- bite: lunge forward, jaws open wide then snap shut
        neck1.xRot += bite * 0.35F;
        head.xRot -= bite * 0.25F;
        jaw.xRot += bite * 0.95F;

        // ---- fire breath: jaw wide open, a slight shudder
        jaw.xRot += breath * 0.7F;
        head.zRot += breath * Mth.sin(age * 1.7F) * 0.03F;

        // ---- walking: diagonal pairs, heavy slow gait
        float w = limbSwing * 0.45F;
        float amt = Math.min(limbSwingAmount, 1.0F) * ground * (1.0F - swim);
        float[] phase = {0, Mth.PI, Mth.PI, 0};
        for (int i = 0; i < 4; i++) {
            float swing = Mth.cos(w + phase[i]);
            legs[i].xRot += swing * 0.7F * amt;
            shins[i].xRot += Math.max(0.0F, -Mth.sin(w + phase[i])) * 0.6F * amt;
        }
        body.zRot += Mth.cos(w) * 0.03F * amt;

        // ---- flying: legs tucked back, neck stretched forward, tail straight
        for (int i = 0; i < 4; i++) {
            legs[i].xRot += fly * (i < 2 ? 0.9F : 1.1F);
            shins[i].xRot += fly * (i < 2 ? 0.8F : 0.5F);
        }
        neck1.xRot += fly * 0.35F;
        head.xRot -= fly * 0.3F;
        tail1.xRot += fly * 0.2F;
        tail2.xRot += fly * 0.1F;

        // ---- swimming: streamlined like flying, the hind legs kicking with each stroke,
        //      and the tail sweeping side to side in a wave that runs down to the tail fin
        if (swim > 0) {
            for (int i = 0; i < 4; i++) {
                legs[i].xRot += swim * (i < 2 ? 1.0F : 1.2F);
                shins[i].xRot += swim * (i < 2 ? 0.8F : 0.4F);
            }
            float kick = Mth.sin(stroke - 0.6F) * (0.1F + 0.2F * pace) * swim;
            legs[2].xRot += kick;
            legs[3].xRot += kick;
            neck1.xRot += swim * 0.3F;
            head.xRot -= swim * 0.25F;
            tail1.xRot += swim * 0.12F;
            float wave = (0.1F + 0.22F * pace) * swim;
            tail1.yRot += Mth.sin(stroke) * wave * 0.5F;
            tail2.yRot += Mth.sin(stroke - 0.8F) * wave * 0.9F;
            tail3.yRot += Mth.sin(stroke - 1.6F) * wave * 1.25F;
            tail4.yRot += Mth.sin(stroke - 2.4F) * wave * 1.6F;
            body.yRot -= Mth.sin(stroke) * wave * 0.12F;      // the body sways a little against the tail
            neck1.yRot += Mth.sin(stroke) * wave * 0.12F;     // and the neck keeps the head steady
        }

        // ---- tail sway
        float sway = (0.12F + 0.06F * fly) * (1.0F - swim);
        tail1.yRot += Mth.sin(age * 0.1F) * sway;
        tail2.yRot += Mth.sin(age * 0.1F - 0.7F) * sway * 1.2F;
        tail3.yRot += Mth.sin(age * 0.1F - 1.4F) * sway * 1.4F;
        tail4.yRot += Mth.sin(age * 0.1F - 2.1F) * sway * 1.6F;
        tail1.yRot -= yaw * 0.15F;

        // ---- wings: folded along the back on the ground, big flaps in the air,
        //      and in water slow rowing strokes like a sea turtle's, swept back and sweeping further back on each down-stroke
        float flap = Mth.sin(age * 0.3F);
        float flapTip = Mth.sin(age * 0.3F - 0.9F);
        float rest = Mth.sin(age * 0.08F) * 0.03F;
        // how far open the wings are: 0 folded, 1 spread. Breathing fire on the ground half-opens them.
        float open = Math.max(Math.max(fly, swim * 0.95F), breath * ground * 0.55F);
        float spread = Math.max(fly, swim);
        boolean rowing = swim > fly;
        float spreadZ = rowing ? -0.05F + Mth.sin(stroke) * (0.3F + 0.25F * pace) : -0.1F + flap * 0.75F;
        float spreadTipZ = rowing ? 0.4F + Mth.sin(stroke - 0.9F) * 0.3F : 0.2F + flapTip * 0.55F;
        float openZ = Mth.lerp(spread, -0.45F, spreadZ);
        float openTipZ = Mth.lerp(spread, 0.55F, spreadTipZ);
        // folded: the arm runs back along the top of the flank, the hand folds back along it,
        // and the membrane hangs down the side, gathered up to under half its depth
        float rX = Mth.lerp(open, -1.45F, 0.0F);
        float rY = Mth.lerp(open, -1.5F, 0.0F) - swim * (0.3F + Mth.sin(stroke - 0.5F) * 0.15F);
        float rZ = Mth.lerp(open, -0.3F + rest, openZ);
        float tipZ = Mth.lerp(open, 2.95F, openTipZ);
        float gathered = Mth.lerp(open, 0.45F, 1.0F);
        wingR.xRot = rX;
        wingR.yRot = rY;
        wingR.zRot = rZ;
        wingR.zScale = gathered;
        wingTipR.zRot = tipZ;
        wingL.xRot = rX;
        wingL.yRot = -rY;
        wingL.zRot = -rZ;
        wingL.zScale = gathered;
        wingTipL.zRot = -tipZ;
    }
}
